('Tutoriat 9 (Video)', 'https://teams.cloud.microsoft/l/meetingrecap?driveId=b%21V72V1b_ypki2lyU6SlaPckU0to9T2QlIqrM_EoP88WtlGxL8BB_qTLRt-slvyd9U&driveItemId=01PDUSWFCFX3HGYI5RQJHKB5HYR57QFERL&sitePath=https%3A%2F%2Funibucro0-my.sharepoint.com%2F%3Av%3A%2Fg%2Fpersonal%2Fandrei-stefan_neacsu_s_unibuc_ro%2FIQBFvs5sI7GCTqD0-I9_ApIrAVZR0LT9tu-vV3dKIt8viZk&fileUrl=https%3A%2F%2Funibucro0-my.sharepoint.com%2Fpersonal%2Fandrei-stefan_neacsu_s_unibuc_ro%2FDocuments%2FRecordings%2FTutoriat+Matematici+Speciale+%2816.05.2026%29-20260516_160910-Meeting+Recording.mp4%3Fweb%3D1&iCalUid=040000008200e00074c5b7101a82e00800000000883de03010e5dc01000000000000000010000000f79423446f829944b83271d72824eb73&threadId=19%3Ameeting_ZjAyODQ5MzMtMGQyZi00YjViLThmZjItYzE0ZmI4NjZkZWE3%40thread.v2&organizerId=ec69925a-baa1-4f3f-b2e1-188029e72ba1&tenantId=08a1a72f-fecd-4dae-8cec-471a2fb7c2f1&callId=99a63b90-8561-4e5d-be4e-a097a8244f45&threadType=Meeting&meetingType=Scheduled&subType=RecapSharingLink_RecapCore&recapType=RecordingAndTranscript', 'tutoriat', 'Video', '2026-05-20 10:00:00');
INSERT INTO announcements (title, body, author, created_at) VALUES 
('Începerea tutoriatului', 'Prima întâlnire va avea loc marți, 17 martie, ora 18:00, în sala 107. Vă așteptăm!', 'Neacșu Andrei Ștefan', '2026-03-07 10:00:00'),
('Platforma Matematici Speciale', 'Începând de azi, platforma online pentru Matematici Speciale aferentă acestui an universitar este disponibilă! Accesul este dedicat doar persoanelor autorizate. Pentru a primi credențiale de autentificare, vă rugăm să contactați unul dintre tutori.', 'Nițuică Andrei Sebastian', '2026-03-18 10:00:00'),
('Acces Platforma Matematici Speciale', 'Accesul este permis și cu conturi personale, dar acestea trebuie să treacă printr-un proces de verificare. În acest sens, după crearea contului pe site, vă rugăm să contactați unul dintre tutori!', 'Neacșu Andrei Ștefan', '2026-03-25 10:00:00'),
('Tutoriat anulat', 'Considerând situația unuia dintre tutori, tutoriatul planificat pentru 7 aprilie 2026 se anulează!', 'Nițuică Andrei Sebastian', '2026-04-06 10:00:00'),
('Tutoriat anulat', 'Considerând situația unuia dintre tutori, tutoriatul planificat pentru 21 aprilie 2026 se anulează!', 'Neacșu Andrei Ștefan', '2026-04-20 10:00:00'),
('Modificare orar', 'DOAR săptămâna aceasta tutoriatul se va desfășura sâmbătă, 25 aprilie, ora 17:00, în regim online! Sesiunea va avea 3 ore pentru a recupera ultimele două tutoriate anulate.', 'Nițuică Andrei Sebastian', '2026-04-22 10:00:00'),
('Sesiune Tutoriat MS (25.04.2026)', 'Aveți link-ul de conectare aferent sesiunii de tutoriat din data de 25 aprilie 2026. LINK: https://teams.microsoft.com/meet/317074262613697?p=fJ1fg5FRcmt6lHzs6E', 'Neacșu Andrei Ștefan', '2026-04-25 16:00:00'),
('Prezență Tutoriat MS (25.04.2026)', 'Aveți mai jos atașat link-ul pentru Google Forms destinat înregistrării prezenței la sesiunea de tutoriat din 25 aprilie 2026. Formularul va rămâne deschis doar pe durata desfășurării tutoriatului. Vă rugăm să vă înregistrați în timp util! LINK: https://forms.gle/bk43ffSReGebRxHM9', 'Nițuică Andrei Sebastian', '2026-04-25 16:30:00'),
('Revenire la programul normal', 'Se revine la programul normal, marțea, între orele 18:00 și 20:00 în sala 107!', 'Neacșu Andrei Ștefan', '2026-04-28 10:00:00'),
('Tutoriat anulat', 'Considerând situația unuia dintre tutori, tutoriatul planificat pentru 5 mai 2026 se anulează!', 'Nițuică Andrei Sebastian', '2026-05-04 10:00:00'),
('Tutoriat anulat', 'Considerând situația unuia dintre tutori, tutoriatul planificat pentru 12 mai 2026 se anulează!', 'Neacșu Andrei Ștefan', '2026-05-11 10:00:00'),
('Modificare orar', 'DOAR săptămâna aceasta tutoriatul se va desfășura mâine, 16 mai, ora 16:00, în regim online! Sesiunea va avea 3 ore pentru a recupera ultimele două tutoriate anulate.', 'Nițuică Andrei Sebastian', '2026-05-15 10:00:00'),
('Sesiune Tutoriat MS (16.05.2026)', 'Aveți link-ul de conectare aferent sesiunii de tutoriat din data de 16 mai 2026. LINK: https://teams.microsoft.com/meet/326639911607467?p=nE9oGkbBYCwoeOBQ8s', 'Neacșu Andrei Ștefan', '2026-05-16 15:00:00'),
('Prezență Tutoriat MS (16.05.2026)', 'Aveți mai jos atașat link-ul pentru Google Forms destinat înregistrării prezenței la sesiunea de tutoriat din 16 mai 2026. Formularul va rămâne deschis doar pe durata desfășurării tutoriatului. Vă rugăm să vă înregistrați în timp util! LINK: https://forms.gle/iPbuWmXsxGWrgm9W7', 'Nițuică Andrei Sebastian', '2026-05-16 15:30:00'),
('Revenire la programul normal', 'Se revine la programul normal, marțea, între orele 18:00 și 20:00 în sala 107!', 'Neacșu Andrei Ștefan', '2026-05-18 10:00:00'),
('Formular de întrebări', 'A fost publicat formularul de întrebări! De acum, vă puteți trimite întrebările pentru sesiunea de recapitulare. Acesta poate fi accesat la adresa: http://www.matematicispeciale.site/formular-intrebari', 'Nițuică Andrei Sebastian', '2026-06-03 10:00:00'),
('Succes în sesiune!', 'Vă urăm succes în sesiune!', 'Neacșu Andrei Ștefan', '2026-06-08 09:00:00'),
('Programare Tutoriat recapitulare', 'Mâine ne vedem în sala 209 de la ora 10:00 la 12:00 pentru a discuta întrebările voastre.', 'Neacșu Andrei Ștefan', '2026-06-08 10:00:00'),
('Succes la examen!', 'Vă urăm mult succes la examenul de Matematici Speciale!', 'Neacșu Andrei Ștefan', '2026-06-15 10:00:00');
